begin;
create table if not exists public.user_devices(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,organization_id uuid references public.organizations(id) on delete cascade,device_fingerprint text not null,device_name text not null default 'Web browser',device_type text not null default 'browser',platform text,browser text,first_ip inet,last_ip inet,first_seen_at timestamptz not null default now(),last_seen_at timestamptz not null default now(),trusted_at timestamptz,revoked_at timestamptz,metadata jsonb not null default '{}'::jsonb,unique(user_id,device_fingerprint));
create index if not exists user_devices_user_seen_idx on public.user_devices(user_id,last_seen_at desc);
alter table public.user_devices enable row level security;
drop policy if exists "users read own devices" on public.user_devices; create policy "users read own devices" on public.user_devices for select using(user_id=auth.uid());
drop policy if exists "users update own devices" on public.user_devices; create policy "users update own devices" on public.user_devices for update using(user_id=auth.uid()) with check(user_id=auth.uid());
create or replace function public.set_device_trust(p_device_id uuid,p_trusted boolean) returns boolean language plpgsql security definer set search_path=public,auth as $$ begin update public.user_devices set trusted_at=case when p_trusted then now() else null end,revoked_at=case when p_trusted then null else revoked_at end where id=p_device_id and user_id=auth.uid(); return found; end $$;
create or replace function public.revoke_user_device(p_device_id uuid) returns boolean language plpgsql security definer set search_path=public,auth as $$ begin update public.user_devices set revoked_at=coalesce(revoked_at,now()),trusted_at=null where id=p_device_id and user_id=auth.uid(); update public.user_sessions set revoked_at=coalesce(revoked_at,now()),revoked_reason='device_revoked' where user_id=auth.uid() and session_fingerprint=(select device_fingerprint from public.user_devices where id=p_device_id); return found; end $$;
revoke all on function public.set_device_trust(uuid,boolean) from public; grant execute on function public.set_device_trust(uuid,boolean) to authenticated;
revoke all on function public.revoke_user_device(uuid) from public; grant execute on function public.revoke_user_device(uuid) to authenticated;
commit;